export type Notification = {
	id: string;
	recipientId: string;
	category: string;
	title: string;
	body: string;
	href: string | null;
	readAt: string | null;
	archivedAt: string | null;
	createdAt: string;
};

export type NotificationPreference = {
	id: string;
	recipientId: string;
	category: string;
	inApp: boolean;
	email: boolean;
	updatedAt: string;
};

export type NotificationCategory = {
	id: string;
	label?: string;
	inApp?: boolean;
	email?: boolean;
};

export type NotificationRecord = Omit<
	Notification,
	"readAt" | "archivedAt" | "createdAt"
> & {
	readAt: Date | null;
	archivedAt: Date | null;
	createdAt: Date;
};
export type NotificationPreferenceRecord = Omit<
	NotificationPreference,
	"updatedAt"
> & { key: string; updatedAt: Date };
export type NotificationList = {
	items: Notification[];
	total: number;
	unreadCount: number;
};
export type {
	SendNotificationInput,
	UpdatePreferencesInput,
	ListNotificationsInput,
} from "./schemas";

import { z } from "zod";

const recipientId = z.string().trim().min(1).max(256);
const category = z.string().trim().min(1).max(100);
export const recipientSchema = z.object({
	recipientId: recipientId.optional(),
});
export const notificationIdSchema = z.object({
	id: z.string().min(1).max(256),
});
export const listNotificationsSchema = recipientSchema.extend({
	status: z.enum(["all", "unread"]).default("all"),
	limit: z.coerce.number().int().min(1).max(100).default(20),
	offset: z.coerce.number().int().min(0).max(1000000).default(0),
});
export const notificationPreferenceSchema = z.object({
	category,
	inApp: z.boolean(),
	email: z.boolean(),
});
export const updatePreferencesSchema = recipientSchema.extend({
	preferences: z
		.array(notificationPreferenceSchema)
		.max(100)
		.refine(
			(values) =>
				new Set(values.map((value) => value.category)).size === values.length,
			"Each category must appear once",
		),
});
export const sendNotificationSchema = z.object({
	recipientId,
	category,
	title: z.string().trim().min(1).max(200),
	body: z.string().max(10000),
	href: z
		.string()
		.max(2048)
		.refine(
			(href) =>
				(href.startsWith("/") &&
					!href.startsWith("//") &&
					!href.includes("\\")) ||
				/^https?:\/\//i.test(href),
			"Use a relative path or HTTP(S) URL",
		)
		.optional(),
});
export type SendNotificationInput = z.input<typeof sendNotificationSchema>;
export type UpdatePreferencesInput = z.input<typeof updatePreferencesSchema>;
export type ListNotificationsInput = z.input<typeof listNotificationsSchema>;

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

const notification = z.object({ id: z.string(), recipientId: z.string() });
export const notificationsPermissions = definePermissions("notifications", {
	inbox: { read: permission(), markAllAsRead: permission() },
	preferences: { read: permission(), update: permission() },
	notification: {
		markAsRead: permission(notification),
		archive: permission(notification),
		send: permission(
			z.object({ recipientId: z.string(), category: z.string() }),
		),
	},
});

"use client";

import { Bell } from "lucide-react";
import {
	PermissionAccess,
	useIdentity,
	usePluginSiteNavigation,
} from "@btst/stack/context";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import { notificationsPermissions } from "../../permissions";
import { NOTIFICATIONS_PLUGIN_ID } from "../constants";
import { useNotifications } from "@btst/plugin-notifications/client/hooks";
import { NotificationList } from "./notification-list";
import { useNotificationsLabels } from "./shared";

export interface NotificationBellProps {
	className?: string;
}

/** Embeds the current user's unread count and recent inbox in application navigation. */
export function NotificationBell(props: NotificationBellProps) {
	const { identity, isPending, error } = useIdentity();
	if (!identity || isPending || error) return null;
	return (
		<PermissionAccess permission={notificationsPermissions.inbox.read()}>
			<NotificationBellContent {...props} />
		</PermissionAccess>
	);
}

function NotificationBellContent({ className }: NotificationBellProps) {
	const { data, isPending, error } = useNotifications({ limit: 5, offset: 0 });
	const { Link, resolve } = usePluginSiteNavigation(NOTIFICATIONS_PLUGIN_ID);
	const labels = useNotificationsLabels();
	return (
		<Popover>
			<PopoverTrigger asChild>
				<button
					type="button"
					className={`notification-bell ${className ?? ""}`}
					aria-label="Notifications"
				>
					<Bell size={20} aria-hidden="true" />
					{!!data?.unreadCount && (
						<span
							className="nt-badge"
							aria-label={`${data.unreadCount} unread notifications`}
						>
							{data.unreadCount > 99 ? "99+" : data.unreadCount}
						</span>
					)}
				</button>
			</PopoverTrigger>
			<PopoverContent
				className="notifications-popover"
				align="end"
				aria-label="Recent notifications"
			>
				<header className="nt-header">
					<h2>{labels.title}</h2>
					<Link href={resolve("notifications/preferences").href}>
						{labels.preferences}
					</Link>
				</header>
				{isPending ? (
					<p role="status">Loading notifications…</p>
				) : error ? (
					<p role="alert">{error.message}</p>
				) : (
					<NotificationList items={data?.items ?? []} empty={labels.empty} />
				)}
				<Link className="nt-inbox-link" href={resolve("notifications").href}>
					View all notifications
				</Link>
			</PopoverContent>
		</Popover>
	);
}

"use client";

import {
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
} from "@btst/stack/context";
import { notificationsPermissions } from "../../permissions";
import type { Notification } from "../../types";
import type { NotificationsPluginOverrides } from "../overrides";
import { NOTIFICATIONS_PLUGIN_ID } from "../constants";
import { useArchiveNotification, useMarkNotificationAsRead } from "@btst/plugin-notifications/client/hooks";

export function NotificationList({
	page,
	items,
	empty,
}: {
	page?: "inbox";
	items: Notification[];
	empty: string;
}) {
	const { pageOverrides } = usePluginOverrides<NotificationsPluginOverrides>(
		NOTIFICATIONS_PLUGIN_ID,
	);
	const Row =
		(page ? pageOverrides?.[page]?.NotificationRow : undefined) ??
		NotificationRow;
	if (!items.length) return <p className="nt-empty">{empty}</p>;
	return (
		<ul className="nt-list" aria-label="Notifications">
			{items.map((item) => (
				<Row key={item.id} item={item} />
			))}
		</ul>
	);
}

function NotificationRow({ item }: { item: Notification }) {
	const markAsRead = useMarkNotificationAsRead();
	const archive = useArchiveNotification();
	const { Link } = usePluginSiteNavigation(NOTIFICATIONS_PLUGIN_ID);
	const facts = { id: item.id, recipientId: item.recipientId };
	const error = markAsRead.error ?? archive.error;
	return (
		<li className="nt-row" data-unread={!item.readAt}>
			<div className="nt-content">
				<span className="nt-category">{item.category}</span>
				<h2>
					{item.href ? <Link href={item.href}>{item.title}</Link> : item.title}
				</h2>
				<p>{item.body}</p>
				<time dateTime={item.createdAt}>
					{new Date(item.createdAt).toISOString().slice(0, 10)}
				</time>
			</div>
			<div className="nt-actions">
				{!item.readAt && (
					<PermissionAccess
						permission={notificationsPermissions.notification.markAsRead(facts)}
					>
						<button
							type="button"
							disabled={markAsRead.isPending || archive.isPending}
							onClick={() => markAsRead.mutate(item.id)}
						>
							Mark as read
						</button>
					</PermissionAccess>
				)}
				<PermissionAccess
					permission={notificationsPermissions.notification.archive(facts)}
				>
					<button
						type="button"
						disabled={markAsRead.isPending || archive.isPending}
						onClick={() => archive.mutate(item.id)}
					>
						Archive
					</button>
				</PermissionAccess>
			</div>
			{error && (
				<p className="nt-error" role="alert">
					{error.message}
				</p>
			)}
		</li>
	);
}

"use client";

import { lazy } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { useIdentity } from "@btst/stack/context";
import { notificationsPermissions } from "../../permissions";
import {
	NotificationsError,
	NotificationsLoading,
	NotificationsNotFound,
} from "./shared";

const Inbox = lazy(() =>
	import("./pages/inbox-page.internal").then((module) => ({
		default: module.InboxPage,
	})),
);
const Preferences = lazy(() =>
	import("./pages/preferences-page.internal").then((module) => ({
		default: module.PreferencesPage,
	})),
);
const boundary = {
	ErrorComponent: NotificationsError,
	LoadingComponent: NotificationsLoading,
	NotFoundComponent: NotificationsNotFound,
	onError: (error: Error) => console.error("[btst/notifications]", error),
};

export function NotificationsPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/notifications"
			permission={notificationsPermissions.inbox.read()}
			PageComponent={Inbox}
		/>
	);
}

export function NotificationPreferencesPageComponent() {
	const { identity } = useIdentity();
	return (
		<ComposedRoute
			key={identity?.id}
			{...boundary}
			path="/notifications/preferences"
			permission={notificationsPermissions.preferences.read()}
			PageComponent={Preferences}
		/>
	);
}

"use client";

import { useState } from "react";
import { PermissionAccess, usePluginSiteNavigation } from "@btst/stack/context";
import { notificationsPermissions } from "../../../permissions";
import { NOTIFICATIONS_PLUGIN_ID } from "../../constants";
import {
	useMarkAllNotificationsAsRead,
	useSuspenseNotifications,
} from "@btst/plugin-notifications/client/hooks";
import { NotificationList } from "../notification-list";
import { NotificationsPage, useNotificationsLabels } from "../shared";

export function InboxPage() {
	const [status, setStatus] = useState<"all" | "unread">("all");
	const [offset, setOffset] = useState(0);
	const params = {
		...(status === "unread" ? { status } : {}),
		limit: 25,
		offset,
	};
	const { data, refetch, isFetching } = useSuspenseNotifications(params);
	const markAll = useMarkAllNotificationsAsRead();
	const { Link, resolve } = usePluginSiteNavigation(NOTIFICATIONS_PLUGIN_ID);
	const labels = useNotificationsLabels();
	return (
		<NotificationsPage
			title={labels.title}
			action={
				<Link href={resolve("notifications/preferences").href}>
					{labels.preferences}
				</Link>
			}
		>
			<div className="nt-toolbar">
				<div className="nt-tabs" aria-label="Filter notifications">
					{(["all", "unread"] as const).map((value) => (
						<button
							type="button"
							key={value}
							aria-pressed={status === value}
							onClick={() => {
								setStatus(value);
								setOffset(0);
							}}
						>
							{value === "all" ? "All" : "Unread"}
						</button>
					))}
				</div>
				<div className="nt-actions">
					<button
						type="button"
						disabled={isFetching}
						onClick={() => void refetch()}
					>
						Refresh
					</button>
					<PermissionAccess
						permission={notificationsPermissions.inbox.markAllAsRead()}
					>
						<button
							type="button"
							disabled={!data.unreadCount || markAll.isPending}
							onClick={() => markAll.mutate()}
						>
							{labels.markAllAsRead}
						</button>
					</PermissionAccess>
				</div>
			</div>
			<p className="nt-count">{data.unreadCount} unread</p>
			{markAll.error && (
				<p className="nt-error" role="alert">
					{markAll.error.message}
				</p>
			)}
			<NotificationList page="inbox" items={data.items} empty={labels.empty} />
			{(offset > 0 || offset + 25 < data.total) && (
				<nav className="nt-pagination" aria-label="Notification pages">
					<button
						type="button"
						disabled={offset === 0}
						onClick={() => setOffset(Math.max(0, offset - 25))}
					>
						Previous
					</button>
					<button
						type="button"
						disabled={offset + 25 >= data.total}
						onClick={() => setOffset(offset + 25)}
					>
						Next
					</button>
				</nav>
			)}
		</NotificationsPage>
	);
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import { PermissionAccess, usePluginSiteNavigation } from "@btst/stack/context";
import { notificationsPermissions } from "../../../permissions";
import type { NotificationPreferenceInput } from "@btst/plugin-notifications/query-keys";
import { NOTIFICATIONS_PLUGIN_ID } from "../../constants";
import {
	useNotificationPreferences,
	useUpdateNotificationPreferences,
} from "@btst/plugin-notifications/client/hooks";
import { NotificationsPage } from "../shared";

export function PreferencesPage() {
	const { data } = useNotificationPreferences();
	const update = useUpdateNotificationPreferences();
	const [draft, setDraft] = useState<
		Record<string, NotificationPreferenceInput>
	>({});
	const [saved, setSaved] = useState(false);
	const [isSaving, setIsSaving] = useState(false);
	const active = useRef(true);
	useLayoutEffect(() => {
		active.current = true;
		return () => {
			active.current = false;
		};
	}, []);
	const { Link, resolve } = usePluginSiteNavigation(NOTIFICATIONS_PLUGIN_ID);
	const preferences = data.map((preference) =>
		Object.hasOwn(draft, preference.category)
			? draft[preference.category]!
			: preference,
	);
	return (
		<NotificationsPage
			title="Notification preferences"
			action={<Link href={resolve("notifications").href}>Back to inbox</Link>}
		>
			<p>Choose how you receive each type of notification.</p>
			<form
				onSubmit={async (event) => {
					event.preventDefault();
					if (isSaving) return;
					setSaved(false);
					setIsSaving(true);
					const edits = Object.values(draft).map(
						({ category, inApp, email }) => ({
							category,
							inApp,
							email,
						}),
					);
					try {
						for (let offset = 0; offset < edits.length; offset += 100) {
							if (!active.current) return;
							await update.mutateAsync(edits.slice(offset, offset + 100));
						}
						if (!active.current) return;
						setDraft({});
						setSaved(true);
					} catch {
						/* The mutation exposes the error below. */
					} finally {
						if (active.current) setIsSaving(false);
					}
				}}
			>
				<fieldset className="nt-preferences" disabled={isSaving}>
					<legend className="nt-sr-only">Delivery channels by category</legend>
					{preferences.length ? (
						preferences.map((preference) => (
							<div className="nt-preference" key={preference.category}>
								<h2>{preference.category}</h2>
								{(["inApp", "email"] as const).map((channel) => (
									<label key={channel}>
										<input
											type="checkbox"
											checked={preference[channel]}
											aria-label={`${preference.category} ${channel === "inApp" ? "in-app" : "email"} notifications`}
											onChange={(event) => {
												setSaved(false);
												setDraft({
													...draft,
													[preference.category]: {
														...preference,
														[channel]: event.target.checked,
													},
												});
											}}
										/>
										{channel === "inApp" ? "In-app" : "Email"}
									</label>
								))}
							</div>
						))
					) : (
						<p>No notification categories are configured yet.</p>
					)}
				</fieldset>
				{update.error && (
					<p className="nt-error" role="alert">
						{update.error.message}
					</p>
				)}
				{saved && <p role="status">Preferences saved.</p>}
				<PermissionAccess
					permission={notificationsPermissions.preferences.update()}
				>
					<button type="submit" disabled={isSaving || !preferences.length}>
						{isSaving ? "Saving…" : "Save preferences"}
					</button>
				</PermissionAccess>
			</form>
		</NotificationsPage>
	);
}

"use client";

import type { ReactNode } from "react";
import type { FallbackProps } from "@btst/stack/client/components";
import { usePluginOverrides } from "@btst/stack/context";
import { NOTIFICATIONS_PLUGIN_ID } from "../constants";
import type { NotificationsPluginOverrides } from "../overrides";

export function useNotificationsLabels() {
	const { localization } = usePluginOverrides<NotificationsPluginOverrides>(
		NOTIFICATIONS_PLUGIN_ID,
	);
	return {
		title: "Notifications",
		preferences: "Preferences",
		empty: "You're all caught up.",
		markAllAsRead: "Mark all as read",
		...localization,
	};
}

export function NotificationsPage({
	title,
	children,
	action,
}: {
	title: string;
	children: ReactNode;
	action?: ReactNode;
}) {
	return (
		<section className="notifications-page">
			<header className="nt-header">
				<h1>{title}</h1>
				{action}
			</header>
			{children}
		</section>
	);
}

export function NotificationsLoading() {
	return (
		<section className="notifications-page" role="status">
			Loading notifications…
		</section>
	);
}

export function NotificationsError({ resetErrorBoundary }: FallbackProps) {
	return (
		<section className="notifications-page" role="alert">
			<h1>Notifications unavailable</h1>
			<p>Check your access and try again.</p>
			<button type="button" onClick={resetErrorBoundary}>
				Try again
			</button>
		</section>
	);
}

export function NotificationsNotFound({ message }: { message: string }) {
	return (
		<section className="notifications-page">
			<h1>Not found</h1>
			<p>{message}</p>
		</section>
	);
}

import type { ComponentType } from "react";
import type { Notification } from "../types";

/** Notification presentation overrides supplied through StackProvider. */
export interface NotificationsPluginOverrides {
	/** Replace inbox rows while preserving the bell and inbox controls. */
	pageOverrides?: {
		inbox?: { NotificationRow?: ComponentType<{ item: Notification }> };
	};
	localization?: Partial<{
		title: string;
		preferences: string;
		empty: string;
		markAllAsRead: string;
	}>;
}
